struct ThreatAwareSystem {
    let systemID: String
    let threats: [Threat]

    func filtered(_ keep: (Threat) -> Bool) -> Self {
        Self(systemID: systemID, threats: threats.filter(keep))
    }
}

let rootkits = system.filtered { $0.type == .rootkit }
let names = system.threats.lazy.filter(\.isKnown).map(\.name).prefix(10)   // lazy
